/* Testes do motor (sem navegador). Uso: node tests/engine.test.js */
'use strict';
const SB = require('./load-engine.js')();
let pass = 0, fail = 0;
function t(name, fn) { try { fn(); pass++; console.log('  ok  ' + name); } catch (e) { fail++; console.log('  FALHA ' + name + '\n        ' + e.message); } }
const eq = (a, b, m) => { if (a !== b) throw new Error(`${m || ''} esperado ${JSON.stringify(b)}, obtido ${JSON.stringify(a)}`); };
const ok = (c, m) => { if (!c) throw new Error(m || 'condição falsa'); };
/** Trilha toda liberada (como um save anterior à v1.5): os testes de outras regras não dependem dela. */
const unlockAll = s => { for (const k of SB.CHAIN_KINDS) s.done[k] = (k === 'items' ? SB.ITEMS : k === 'biz' ? SB.BUSINESSES : SB.chainList(k)).map(x => x.id); return s; };
const newbie = () => SB.defaultState('Teste', 'Recife');
/** Ponto de partida dos testes de outras regras: trilha liberada e R$ 1.900 no bolso (o começo antigo). */
const fresh = () => { const s = unlockAll(newbie()); s.cash = 1900; for (const c of SB.FEAT_CATS) s.feats[c] = 3; return s; }; // feitos já pagos: não mexem no respeito dos testes
const withGang = (n = 2) => { const s = fresh(); s.respect = 40; s.cash = 5000; SB.perform(s, 'foundGang', 'Bonde'); while (s.crew.length < n) { s.crewLastRecruit = 0; s.energy = 100; s.cash += 2000; SB.perform(s, 'recruit', 'musculo'); } return s; };
SB.setRandom(SB.seeded(123));

console.log('Personagem iniciante e limites');
t('estado inicial é válido e reidratável; começa sem dinheiro', () => { const r = SB.parseSave(JSON.stringify(newbie())); ok(r.ok, r.error); eq(r.state.cash, 0); eq(r.state.bank, 0); });
t('primeiros passos: roubo que falha antes do primeiro sucesso não dá cadeia', () => { const s = newbie(); s.heat = 100; eq(SB.arrestChance(s, SB.mission('cofre')), 0); s.successful = 1; ok(SB.arrestChance(s, SB.mission('cofre')) > 0); const v = newbie(); v.tutorial.done = true; ok(SB.arrestChance(v, SB.mission('correria')) > 0); });
t('missão sem energia é recusada sem alterar estado', () => { const s = fresh(); s.energy = 5; const c = JSON.stringify(s); const r = SB.perform(s, 'mission', 'correria'); eq(r.ok, false); eq(JSON.stringify(s), c); });
t('missão bloqueada por respeito', () => { const s = fresh(); eq(SB.perform(s, 'mission', 'cofre').ok, false); });
t('missão exclusiva só no bairro (e com a arma exigida)', () => { const s = fresh(); s.respect = 50; ok(SB.missionLock(s, SB.mission('carga')).includes('Cais')); s.district = 'cais'; ok(SB.missionLock(s, SB.mission('carga')).includes('arma')); s.gear.arma = 'peixeira'; eq(SB.missionLock(s, SB.mission('carga')), ''); });
t('chances iniciais coerentes (fácil ≥ 75%, cofre impossível)', () => { const s = fresh(); ok(SB.missionChance(s, SB.mission('correria')) >= 75); ok(SB.missionChance(s, SB.mission('cofre')) <= 15); });
t('detido não treina, viaja nem compra; banco continua', () => { const s = fresh(); s.jail = 2; s.cash = 9000; for (const [a, x] of [['train', 'astucia'], ['travel', 'cais'], ['buy', 'bar'], ['mission', 'correria']]) eq(SB.perform(s, a, x).ok, false, a); eq(SB.perform(s, 'bank', 'deposit', 100).ok, true); });
t('fiança liberta e cobra o custo', () => { const s = fresh(); s.jail = 2; s.cash = 5000; const c = SB.bailCost(s); eq(SB.perform(s, 'bail').ok, true); eq(s.jail, 0); eq(s.cash, 5000 - c); });
t('fiança com pouco dinheiro é recusada', () => { const s = fresh(); s.jail = 3; s.cash = 10; eq(SB.perform(s, 'bail').ok, false); });

console.log('Economia');
t('depósito cobra 3% e saque é gratuito', () => { const s = fresh(); SB.perform(s, 'bank', 'deposit', 1000); eq(s.bank, 1000); eq(s.cash, 870); SB.perform(s, 'bank', 'withdraw', 1000); eq(s.cash, 1870); });
t('maxDeposit nunca excede o caixa', () => { for (const c of [0, 1, 2, 33, 103, 1900, 99999]) { const s = fresh(); s.cash = c; const v = SB.maxDeposit(s); if (v > 0) { eq(SB.perform(s, 'bank', 'deposit', v).ok, true, 'c=' + c); ok(s.cash >= 0); } } });
t('valores bancários inválidos recusados', () => { const s = fresh(); for (const v of [0, -1, 1.5, NaN, Infinity, 1e20]) eq(SB.perform(s, 'bank', 'deposit', v).ok, false, String(v)); });
t('patrimônio conta negócio pela revenda (60%)', () => { const s = fresh(); s.cash = 1250; SB.perform(s, 'buy', 'bar'); eq(SB.patrimony(s), 750); });
t('venda devolve 60%', () => { const s = fresh(); s.cash = 1250; SB.perform(s, 'buy', 'bar'); SB.perform(s, 'sell', 'bar'); eq(s.cash, 750); });
t('Bicheiro paga 12% menos e o negócio de rua rende 35% mais (a casa da noite não)', () => { const s = fresh(); s.career = 'empreendedor'; s.cash = 2850; SB.perform(s, 'buy', 'oficina'); eq(s.cash, 342); const base = fresh(); eq(Math.round(SB.businessIncome(s, SB.business('oficina'))), Math.round(SB.businessIncome(base, SB.business('oficina')) * 1.35)); eq(Math.round(SB.businessIncome(s, SB.business('bar'))), Math.round(SB.businessIncome(base, SB.business('bar')))); });
t('crise reduz renda de negócios', () => { const s = fresh(); s.businesses = ['mercado']; const a = SB.income(s); s.events = [{ id: 'crise', start: 1, until: 4, district: null }]; ok(SB.income(s) < a); });
t('carnaval multiplica a Casa de Shows', () => { const s = fresh(); s.businesses = ['show']; const a = SB.income(s); s.events = [{ id: 'carnaval', start: 1, until: 3, district: null }]; ok(SB.income(s) >= a * 1.7); });
t('custo de treino cresce de forma superlinear', () => { const s = fresh(); const c1 = SB.trainCost(s, 'astucia'); s.stats.astucia = 30; ok(SB.trainCost(s, 'astucia') > c1 * 3); });
t('limite de 3 treinos por dia', () => { const s = fresh(); s.cash = 99999; for (let i = 0; i < 3; i++) { s.energy = 100; eq(SB.perform(s, 'train', 'forca').ok, true); } s.energy = 100; eq(SB.perform(s, 'train', 'forca').ok, false); });
t('excesso de dinheiro não quebra fórmulas', () => { const s = fresh(); s.cash = 1e11; s.bank = 1e11; SB.perform(s, 'mission', 'correria'); ok(Number.isSafeInteger(s.cash)); ok(Number.isSafeInteger(SB.patrimony(s))); });

console.log('Repetição e diversidade');
t('repetir a mesma missão reduz chance e recompensa', () => { const s = fresh(); s.cash = 0; const m = SB.mission('correria'); const c0 = SB.missionChance(s, m), r0 = SB.missionRewardMult(s, m); s.today.missions.correria = 3; ok(SB.missionChance(s, m) < c0); ok(SB.missionRewardMult(s, m) < r0); });
t('vigilância local sobe com missões e cai no dia seguinte', () => { const s = fresh(); SB.perform(s, 'mission', 'correria'); ok(s.dstate.centro.vigil > 0); const v = s.dstate.centro.vigil; SB.perform(s, 'nextDay'); ok(s.dstate.centro.vigil < v || s.events.some(e => e.id === 'operacao')); });
t('cofre só uma vez por dia', () => { const s = fresh(); s.respect = 200; s.stats.astucia = 40; s.energy = 100; SB.perform(s, 'mission', 'cofre'); s.jail = 0; s.energy = 100; eq(SB.perform(s, 'mission', 'cofre').ok, false); });
t('respeito diminui em missões fáceis demais', () => { const s = fresh(); s.respect = 200; eq(SB.respectGain(s, SB.mission('correria')), 1); });
t('1000 ações seguidas com energia infinita mantêm invariantes', () => { const s = fresh(); s.respect = 300; s.stats.astucia = 60; for (let i = 0; i < 1000; i++) { s.energy = 100; s.jail = 0; SB.perform(s, 'mission', 'deposito'); } ok(s.heat <= 100 && s.cash >= 0 && Number.isInteger(s.cash)); ok(SB.missionChance(s, SB.mission('deposito')) <= 95); });

console.log('Gangue e facções');
t('operação coletiva: 1 por dia e exige 2 integrantes', () => { const s = withGang(2); s.energy = 100; eq(SB.perform(s, 'gangOp').ok, true); s.energy = 100; eq(SB.perform(s, 'gangOp').ok, false); });
t('gangue grande tem chance maior que a pequena', () => { const a = withGang(2), b = withGang(7); a.energy = b.energy = 100; ok(SB.gangOdds(b) > SB.gangOdds(a)); });
t('equipe limitada a 8', () => { const s = withGang(8); s.crewLastRecruit = 0; s.cash = 99999; s.energy = 100; eq(SB.perform(s, 'recruit', 'olheiro').ok, false); });
t('ânimo baixo pode causar deserção', () => { let left = 0; for (let i = 0; i < 40; i++) { const s = withGang(5); s.crewMorale = 5; s.cash = 0; SB.perform(s, 'nextDay'); if (s.crew.length < 5) left++; } ok(left > 0, 'nenhuma deserção em 40 tentativas'); });
t('integrantes sobem de nível', () => { const s = withGang(3); for (let i = 0; i < 60; i++) { s.today.op = false; s.energy = 100; s.jail = 0; s.health = 100; s.hospital = 0; SB.perform(s, 'gangOp'); } ok(s.crew.some(m => m.level > 1)); });
t('trégua exige relação +35 e bloqueia confronto e disputa', () => { const s = withGang(3); eq(SB.perform(s, 'pact', 'esquina').ok, false); s.factions.esquina.relation = 40; s.energy = 100; s.cash = 5000; eq(SB.perform(s, 'pact', 'esquina').ok, true); s.influence.centro = 40; s.factions.esquina.lastActionDay = 0; s.energy = 100; eq(SB.perform(s, 'clash', 'esquina').ok, false); eq(SB.perform(s, 'dispute').ok, false); });
t('trégua seguinte custa mais e tem carência', () => { const s = withGang(3); s.factions.esquina.relation = 60; s.cash = 9000; s.energy = 100; const c1 = SB.pactCost(s, 'esquina'); SB.perform(s, 'pact', 'esquina'); ok(SB.pactCost(s, 'esquina') > c1); s.day = s.factions.esquina.truceUntil + 1; s.factions.esquina.lastActionDay = 0; s.energy = 100; eq(SB.perform(s, 'pact', 'esquina').ok, false); });
t('trégua impede retaliação e avanço onde você tem influência', () => { const s = withGang(3); s.influence.centro = 30; s.influence.vila = 30; s.factions.esquina.relation = -80; s.factions.esquina.tension = 90; s.factions.esquina.truceUntil = 30; const before = s.influence.centro; for (let i = 0; i < 5; i++) SB.perform(s, 'nextDay'); ok(!s.factions.esquina.lastMove.startsWith('Retaliação de Esquina'), s.factions.esquina.lastMove); ok(s.influence.centro >= before - 5); });
t('romper acordo pune relação com todas as facções', () => { const s = withGang(3); s.factions.aurora.relation = 50; s.factions.aurora.truceUntil = 10; const d0 = s.factions.docas.relation; eq(SB.perform(s, 'breakDeal', 'aurora').ok, true); ok(s.factions.aurora.relation <= 10); ok(s.factions.docas.relation < d0); eq(s.treachery, 1); ok(s.achievements.traidor); });
t('aliança: requisitos, contribuição diária e inimigo do aliado', () => { const s = withGang(3); s.gangLevel = 2; s.factions.esquina.relation = 70; s.cash = 5000; s.energy = 100; const d0 = s.factions.docas.relation; eq(SB.perform(s, 'alliance', 'esquina').ok, true); ok(s.factions.docas.relation < d0); const c = s.cash; SB.perform(s, 'nextDay'); ok(s.factions.esquina.allied); ok(SB.clashOdds(s, 'cais') >= 15); ok(s.log[0].msg.includes('Contribuição')); ok(s.cash !== c); });
t('rival dominante: confronto mais difícil', () => { const a = withGang(3), b = withGang(3); a.influence.centro = b.influence.centro = 30; b.presence.centro.esquina = 95; b.factions.esquina.power = 90; ok(SB.clashOdds(b, 'centro') < SB.clashOdds(a, 'centro')); });
t('facções hostis retaliam ao longo do tempo', () => { const s = withGang(3); for (const f of SB.FACTIONS) { s.factions[f.id].relation = -90; s.factions[f.id].tension = 95; } s.influence.cais = 50; s.influence.centro = 50; for (let i = 0; i < 12; i++) { SB.perform(s, 'nextDay'); for (const f of SB.FACTIONS) s.factions[f.id].tension = 95; } ok(s.gangStats.retaliations > 0); });
t('IA: liderança de bairro pode mudar', () => { let changed = 0; for (let k = 0; k < 20; k++) { const s = fresh(); const init = SB.DISTRICTS.map(d => SB.leader(s, d.id).id).join(); while (s.day < 30) SB.perform(s, 'nextDay'); if (SB.DISTRICTS.map(d => SB.leader(s, d.id).id).join() !== init) changed++; } ok(changed > 0, 'território nunca mudou em 20 temporadas'); });
t('controle de bairro gera tributo', () => { const s = fresh(); s.influence.jardim = 80; s.presence.jardim.aurora = 10; ok(SB.controlled(s, 'jardim')); const c = s.cash; s.district = 'jardim'; SB.perform(s, 'nextDay'); ok(s.cash > c); ok(s.seasonStats.controlDays.jardim >= 1 || !SB.controlled(s, 'jardim')); });

console.log('Temporada');
t('não encerra antes do dia 30', () => { const s = fresh(); eq(SB.perform(s, 'endSeason').ok, false); });
t('29 viradas levam ao dia 30 e a 31ª é recusada', () => { const s = fresh(); let n = 0; while (SB.perform(s, 'nextDay').ok) n++; eq(n, 29); eq(s.day, 30); });
t('virada de temporada preserva histórico, conquistas e recordes', () => { const s = fresh(); s.achievements.primeira = 1; s.day = 30; s.cash = 30000; const r = SB.perform(s, 'endSeason'); const n = r.state; eq(n.season, 2); eq(n.day, 1); eq(n.seasonHistory.length, 1); ok(n.achievements.primeira); ok(n.records.fortuna >= 30000); ok(n.cash > 0 && n.cash <= 1200 + 600 + 800, String(n.cash)); });
t('legado inicial é limitado (sem bola de neve)', () => { const s = fresh(); s.day = 30; s.cash = 1e9; const n = SB.perform(s, 'endSeason').state; ok(n.cash <= 4500, String(n.cash)); });
t('rival histórico herdado', () => { const s = fresh(); s.day = 30; s.factions.docas.grudge = 5; const n = SB.perform(s, 'endSeason').state; eq(n.nemesis, 'docas'); ok(n.factions.docas.relation < -20); });
t('a meta saiu: escolher é recusado e não muda nada', () => { const s = fresh(); const b = JSON.stringify(s); eq(SB.perform(s, 'goal', 'renome').ok, false); eq(JSON.stringify(s), b); });
t('save antigo no meio do guia, depois da meta, volta um passo (bank continua bank)', () => { const s = fresh(); const o = JSON.parse(SB.serialize ? SB.serialize(s) : JSON.stringify(s)); o.tutorial = { step: 7, done: false }; const r = SB.parseSave(JSON.stringify(o)); ok(r.ok, r.error); eq(SB.TUTORIAL[r.state.tutorial.step].id, 'bank'); const o2 = JSON.parse(JSON.stringify(r.state)); eq(SB.parseSave(JSON.stringify(o2)).state.tutorial.step, r.state.tutorial.step, 'save novo não volta de novo'); });
t('eventos fixos: Carnaval no dia 9', () => { const s = fresh(); while (s.day < 9) SB.perform(s, 'nextDay'); ok(SB.activeEvents(s).some(e => e.id === 'carnaval')); });

console.log('Salvamentos');
const v04 = { schema: 1, name: 'Antigo', city: 'Salvador', season: 3, day: 12, cash: 4200, bank: 800, energy: 55, heat: 33, respect: 77, stats: { astucia: 12, forca: 6, labia: 5, influencia: 9 }, district: 'cais', jail: 0, businesses: ['bar', 'oficina'], gangName: 'Os Antigos', gangLevel: 2, successful: 40, failed: 9, seasonHistory: [{ season: 1, respect: 100, money: 9000, goal: 'capital', goalComplete: true }], log: [{ day: 12, msg: 'oi' }], eventIndex: 1, career: 'articulador', goal: 'dominio', influence: { centro: 30, cais: 22, jardim: 0, industrial: 0, vila: 5 }, rivals: { centro: 20, cais: 50, jardim: 28, industrial: 31, vila: 34 }, newsPending: null, nextBonus: 0, goalWins: 1, crewSize: 5, crewMorale: 61, crewLastRecruit: 11, crewLastRally: 0, factions: { esquina: { relation: 20, tension: 30, truceUntil: 14, lastActionDay: 12 }, docas: { relation: -50, tension: 60, truceUntil: 0, lastActionDay: 0 }, aurora: { relation: 0, tension: 10, truceUntil: 0, lastActionDay: 0 } }, gangStats: { confrontWins: 3, confrontLosses: 1, pacts: 2, dialogs: 4, retaliations: 2, groupWins: 6 } };
t('save da 0.4 migra integralmente', () => { const r = SB.parseSave(JSON.stringify(v04)); ok(r.ok, r.error); const s = r.state; eq(s.schema, 2); eq(s.cash, 4200); eq(s.crew.length, 5); eq(s.presence.cais.docas, 50); eq(s.factions.esquina.truceUntil, 14); eq(s.events[0].id, 'fiscalizacao'); eq(s.seasonHistory[0].goalComplete, true); eq(s.gangStats.groupWins, 6); });
t('save migrado é jogável por uma temporada', () => { const s = SB.parseSave(JSON.stringify(v04)).state; while (s.day < 30) { SB.perform(s, 'mission', 'carga'); SB.perform(s, 'nextDay'); } eq(SB.perform(s, 'endSeason').ok, true); });
t('arquivo de exportação da 0.4 (envelope) é aceito', () => { ok(SB.parseSave(JSON.stringify({ game: 'Submundo Brasil', version: '0.4', save: v04 })).ok); });
t('JSON corrompido é recusado com motivo', () => { const r = SB.parseSave('{"schema":1,'); eq(r.ok, false); ok(r.error.length > 5); });
t('schema desconhecido é recusado', () => { eq(SB.parseSave(JSON.stringify({ ...v04, schema: 99 })).ok, false); });
t('dia fora da faixa é recusado', () => { eq(SB.parseSave(JSON.stringify({ ...v04, day: 31 })).ok, false); });
t('valores extremos são limitados', () => { const r = SB.parseSave(JSON.stringify({ ...v04, cash: 1e30, energy: 9999, heat: -50, jail: 400, stats: { astucia: -3, forca: 'x', labia: 1e15, influencia: 2.7 } })); ok(r.ok); const s = r.state; eq(s.cash, 1e12); eq(s.energy, 100); eq(s.heat, 0); eq(s.jail, 5); eq(s.stats.astucia, 1); eq(s.stats.forca, 4); eq(s.stats.influencia, 3); ok(r.notes.length > 0); });
t('campos com HTML são texto puro (sem chaves extras)', () => { const r = SB.parseSave(JSON.stringify({ ...v04, evil: '<script>', seasonHistory: [{ season: '<img>', money: '1' }] })); ok(r.ok); eq(r.state.evil, undefined); eq(r.state.seasonHistory[0].season, 0); });
t('ida e volta schema 2 é estável', () => { const s = SB.parseSave(JSON.stringify(v04)).state; const a = JSON.stringify(s); eq(JSON.stringify(SB.parseSave(a).state), a); });
t('checksum detecta alteração', () => { const p = SB.exportPayload(fresh()); eq(SB.checksum(JSON.stringify(p.save)), p.checksum); p.save.cash = 999999; ok(SB.checksum(JSON.stringify(p.save)) !== p.checksum); });

console.log('Cidades e primeiros passos');
t('seis cidades com 5 bairros, 3 grupos e 5 negócios nomeados', () => { eq(SB.CITIES.length, 6); for (const c of SB.CITIES) { eq(Object.keys(c.districts).length, 5); eq(Object.keys(c.factions).length, 3); eq(Object.keys(c.biz).length, 5); ok(c.traitDesc.length > 10); } });
t('nomes mudam com a cidade e voltam', () => { SB.applyCity('São Paulo'); eq(SB.district(null, 'cais').name, 'Terminal de Cargas'); eq(SB.faction('aurora').short, 'Garoa'); SB.applyCity('Rio de Janeiro'); eq(SB.district(null, 'cais').name, 'Cais da Guanabara'); });
t('cidade desconhecida em save vira Rio de Janeiro', () => { eq(SB.parseSave(JSON.stringify({ ...v04, city: 'Atlântida' })).state.city, 'Rio de Janeiro'); });
t('Recife: viagem custa metade e nenhuma energia', () => { const s = SB.defaultState('T', 'Recife'); s.cash = 1900; SB.perform(s, 'travel', 'cais'); eq(s.cash, 1900 - 45); eq(s.energy, 100); });
t('Porto Alegre: treino 10% mais barato', () => { ok(SB.trainCost(SB.defaultState('T', 'Porto Alegre'), 'forca') < SB.trainCost(SB.defaultState('T', 'Recife'), 'forca')); });
t('São Paulo e BH: bônus de negócios', () => { const mk = c => { const s = SB.defaultState('T', c); s.businesses = ['bar']; return SB.income(s); }; ok(mk('São Paulo') > mk('Recife')); ok(mk('Belo Horizonte') > mk('São Paulo')); });
t('Salvador: Carnaval de 5 dias; Rio: 4; demais: 3', () => { const len = c => { const s = SB.defaultState('T', c); while (s.day < 9) SB.perform(s, 'nextDay'); const e = s.events.find(x => x.id === 'carnaval'); return e.until - e.start + 1; }; eq(len('Salvador'), 5); eq(len('Rio de Janeiro'), 4); eq(len('Recife'), 3); });
t('textos de eventos usam nomes da cidade', () => { const s = SB.defaultState('T', 'Belo Horizonte'); SB.applyCity(s.city); s.events = [{ id: 'carnaval', start: 1, until: 3, district: null }]; const d = SB.eventDesc(SB.activeEvents(s)[0]); ok(d.includes('Mercado Velho') && d.includes('Buteco') && !d.includes('{'), d); });
t('primeiros passos na ordem do ciclo: roubar, arma, noite, treino, dormir, banco, bando', () => { const s = fresh(); SB.setRandom(SB.seeded(9)); eq(SB.TUTORIAL.map(x => x.id).join(), 'career,mission,gear,night,train,day,bank,gang'); SB.perform(s, 'career', 'operador'); eq(SB.tutorialStep(s).id, 'mission'); SB.perform(s, 'gig'); eq(SB.tutorialStep(s).id, 'mission'); const r = SB.perform(s, 'mission', 'correria'); ok(r.lines.some(l => l.includes('Primeiros passos 2/8'))); s.jail = 0; s.hospital = 0; eq(SB.tutorialStep(s).id, 'gear'); SB.perform(s, 'buyItem', 'porrete'); eq(SB.tutorialStep(s).id, 'night'); s.energy = 50; SB.perform(s, 'night', 'boteco'); eq(SB.tutorialStep(s).id, 'night'); SB.perform(s, 'dose', 'cerveja'); eq(SB.tutorialStep(s).id, 'train'); SB.perform(s, 'train', 'forca'); eq(SB.tutorialStep(s).id, 'day'); SB.perform(s, 'nextDay'); s.jail = 0; eq(SB.tutorialStep(s).id, 'bank'); SB.perform(s, 'bank', 'deposit', 100); eq(SB.tutorialStep(s).id, 'gang'); s.respect = 40; s.cash = 3000; SB.perform(s, 'foundGang', 'Bonde'); eq(s.tutorial.done, true); });
t('pular guia encerra sem recompensa', () => { const s = fresh(); const c = s.cash; eq(SB.perform(s, 'skipTutorial').ok, true); eq(s.cash, c); eq(SB.perform(s, 'skipTutorial').ok, false); });
t('save antigo em andamento não é forçado ao guia; nova temporada também não', () => { eq(SB.parseSave(JSON.stringify(v04)).state.tutorial.done, true); const s = fresh(); s.day = 30; eq(SB.perform(s, 'endSeason').state.tutorial.done, true); });
t('o placar é o respeito e o título é a patente', () => { const s = fresh(); s.respect = 95; const sc = SB.seasonScore(s); eq(sc.score, 95); eq(sc.title, 'Linha de frente'); eq(sc.next.title, 'Gerente do movimento'); eq(sc.next.at, 150); });

console.log('Feira do Rolo, Galpão e noite (v0.7)');
const rich = () => { const s = fresh(); s.cash = 30000; s.respect = 200; return s; };
t('estado novo com v0.7 faz ida e volta idêntica', () => { const s = rich(); SB.perform(s, 'buyItem', 'moto'); SB.perform(s, 'buyGood', 'erva', 7); SB.perform(s, 'buildLab', 'alambique'); SB.perform(s, 'night', 'boteco'); const a = JSON.stringify(s); eq(JSON.stringify(SB.parseSave(a).state), a); });
t('save antigo ganha equipamento, galpão e mercado padrão', () => { const s = SB.parseSave(JSON.stringify(v04)).state; eq(s.gear.arma, null); eq(s.goods.erva, 0); ok(s.market.cais.po >= 60); eq(s.labs.alambique, 0); ok(s.exportDeal.day >= s.day); });
t('save adulterado: item em espaço errado, carga e mercado limitados', () => { const s = fresh(); s.gear = { arma: 'moto', protecao: 'x', veiculo: 'fuzil' }; s.goods.po = 1e9; s.market.centro.po = 9999; s.labs.alambique = 77; const n = SB.parseSave(JSON.stringify(s)).state; eq(n.gear.arma, null); eq(n.gear.veiculo, null); eq(n.goods.po, 9999); eq(n.market.centro.po, 150); eq(n.labs.alambique, 3); });
t('item exige respeito e dinheiro; o que foi comprado é seu e dá para usar de novo', () => { const s = fresh(); eq(SB.perform(s, 'buyItem', 'fuzil').ok, false); s.cash = 1000; eq(SB.perform(s, 'buyItem', 'soco').ok, true); eq(s.cash, 1000 - SB.item('soco').cost); s.cash = 3000; s.respect = 20; eq(SB.perform(s, 'buyItem', 'peixeira').ok, true); eq(s.cash, 3000 - SB.item('peixeira').cost, 'sem devolução'); eq(s.gear.arma, 'peixeira'); ok(s.owned.includes('soco') && s.owned.includes('peixeira')); eq(SB.perform(s, 'buyItem', 'peixeira').ok, false); const c = JSON.stringify(s); eq(SB.perform(s, 'buyItem', 'soco').ok, false, 'já é seu'); eq(JSON.stringify(s), c); const m = s.cash; eq(SB.perform(s, 'equip', 'soco').ok, true); eq(s.gear.arma, 'soco'); eq(s.cash, m, 'usar é de graça'); eq(SB.perform(s, 'equip', 'soco').ok, false); eq(SB.perform(s, 'equip', 'fuzil').ok, false, 'não é seu'); });
t('arma melhora confronto e serviços de Força; proteção e veículo reduzem detenção', () => { const a = withGang(3), b = withGang(3); a.influence.centro = b.influence.centro = 30; b.gear.arma = 'pistola'; eq(SB.clashOdds(b, 'centro'), SB.clashOdds(a, 'centro') + 9); const m = SB.mission('mercadoria'); ok(SB.missionChance(b, m) > SB.missionChance(a, m)); ok(SB.missionChance(b, SB.mission('cartao')) > SB.missionChance(a, SB.mission('cartao')), 'arma ajuda até no golpe, menos'); a.successful = b.successful = 1; b.gear.protecao = 'colete'; b.gear.veiculo = 'moto'; { const d = SB.mission('deposito'); eq(SB.arrestChance(b, d), SB.arrestChance(a, d) - 17, 'colete 5 + moto 6 + 3 de cada equipado'); } });
t('veículo dá carga e viagem sem energia', () => { const s = rich(); eq(SB.cargoCap(s), 30); SB.perform(s, 'buyItem', 'opala'); eq(SB.cargoCap(s), 90); SB.perform(s, 'travel', 'vila'); eq(s.energy, 100); });
t('mercadoria: limites de respeito, espaço, dinheiro e energia', () => { const s = fresh(); eq(SB.perform(s, 'buyGood', 'po', 1).ok, false); eq(SB.perform(s, 'buyGood', 'cigarro', 31).ok, false); eq(SB.perform(s, 'buyGood', 'cigarro', 0).ok, false); eq(SB.perform(s, 'buyGood', 'cigarro', 2.5).ok, false); s.energy = 2; eq(SB.perform(s, 'buyGood', 'cigarro', 5).ok, false); s.energy = 100; s.cash = 10; eq(SB.perform(s, 'buyGood', 'cigarro', 20).ok, false); eq(SB.perform(s, 'sellGood', 'cigarro', 1).ok, false); });
t('comprar encarece e vender barateia o preço local', () => { const s = rich(); const f = s.market.centro.eletro; SB.perform(s, 'buyGood', 'eletro', 20); ok(s.market.centro.eletro > f); const f2 = s.market.centro.eletro; SB.perform(s, 'sellGood', 'eletro', 20); ok(s.market.centro.eletro < f2); });
t('comprar e revender no mesmo lugar dá prejuízo (sem moto-contínuo)', () => { const s = rich(); const c = s.cash; for (let i = 0; i < 20; i++) { s.energy = 100; SB.perform(s, 'buyGood', 'eletro', 20); SB.perform(s, 'sellGood', 'eletro', 20); } ok(s.cash < c, 'lucro indevido'); });
t('blitz: carga pesada e vigilância alta podem apreender metade', () => { let hit = 0; for (let i = 0; i < 60; i++) { const s = rich(); s.goods.po = 30; s.heat = 90; ok(SB.blitzChance(s) > 20); SB.perform(s, 'travel', 'vila'); if (s.goods.po === 15) hit++; } ok(hit > 0 && hit < 60); const e = fresh(); eq(SB.blitzChance(e), 0); });
t('comprador de fora: dia, lugar, limite e uma vez por dia', () => { const s = rich(); s.goods.cigarro = 30; s.district = 'cais'; eq(SB.perform(s, 'exportGoods').ok, false); s.day = 5; s.district = 'centro'; eq(SB.perform(s, 'exportGoods').ok, false); s.district = 'cais'; const c = s.cash; eq(SB.perform(s, 'exportGoods').ok, true); eq(s.cash, c + 30 * SB.exportPrice(SB.good('cigarro'))); s.goods.cigarro = 5; eq(SB.perform(s, 'exportGoods').ok, false); ok(s.achievements.exportador); });
t('novo comprador é marcado a cada 5 dias', () => { const s = fresh(); while (s.day < 6) SB.perform(s, 'nextDay'); eq(s.exportDeal.day, 10); });
t('produção rende por dia, cobra custo e para com galpão cheio', () => { const s = rich(); SB.perform(s, 'buildLab', 'alambique'); eq(SB.cargoCap(s), 70); const c = s.cash; s.heat = 0; SB.perform(s, 'nextDay'); eq(s.goods.bebida, 7); ok(s.cash <= c - 30); s.goods.cigarro = SB.cargoCap(s) - s.goods.bebida; SB.perform(s, 'nextDay'); eq(s.goods.bebida, 7); });
t('batida policial só com vigilância acima de 40', () => { const s = rich(); eq(SB.raidChance(s), 0); s.heat = 90; eq(SB.raidChance(s), 25); let raided = 0; for (let i = 0; i < 40; i++) { const x = rich(); SB.perform(x, 'buildLab', 'alambique'); x.goods.bebida = 9; x.heat = 100; SB.perform(x, 'nextDay'); if (x.labDown.alambique) { raided++; eq(x.goods.bebida, 0); } } ok(raided > 0); });
t('noite: entrada, doses, ressaca amanhã, três saídas por dia e entrada crescente', () => { const s = rich(); s.energy = 20; let c = s.cash; eq(SB.perform(s, 'night', 'pagode').ok, true); eq(s.energy, 20); eq(s.cash, c - 40); eq(SB.perform(s, 'night', 'pagode').ok, false); c = s.cash; eq(SB.perform(s, 'dose', 'pinga').ok, true); eq(s.energy, 30); eq(s.cash, c - 30); eq(SB.perform(s, 'dose', 'bala').ok, false); c = s.cash; SB.perform(s, 'night', 'boteco'); eq(s.cash, c - 15); c = s.cash; SB.perform(s, 'night', 'baile'); eq(s.cash, c - 120); eq(SB.perform(s, 'night', 'boteco').ok, false); eq(s.ressaca, 1); s.energy = 0; SB.perform(s, 'nextDay'); eq(s.ressaca, 0); eq(s.today.venue, null); const f = rich(); eq(SB.perform(f, 'night', 'boteco').ok, false); });
t('categoria Comércio pontua o lucro com mercadorias', () => { const s = fresh(); s.trade.sold = 10500; s.trade.spent = 1500; const c = SB.seasonScore(s).cats.find(x => x.id === 'comercio'); eq(c.value, 9000); eq(c.medal, 2); });
t('patrimônio conta estoque, equipamento e produção', () => { const s = fresh(); const p0 = SB.patrimony(s); s.goods.eletro = 10; s.gear.veiculo = 'moto'; s.labs.alambique = 1; eq(SB.patrimony(s), p0 + 840 + SB.item('moto').cost * .5 + 1000); });

console.log('Saúde, hospital e duelos (v0.8)');
t('save antigo entra com saúde cheia e sem internação', () => { const s = SB.parseSave(JSON.stringify(v04)).state; eq(s.health, 100); eq(s.hospital, 0); eq(s.duelStats.wins, 0); });
t('saúde e internação adulteradas são limitadas', () => { const s = fresh(); s.health = -50; s.hospital = 99; s.beaten = { rei: 1e9, falso: 3 }; const n = SB.parseSave(JSON.stringify(s)).state; eq(n.health, 0); eq(n.hospital, 5); eq(n.beaten.rei, 999); eq(n.beaten.falso, undefined); });
t('equipamento e força aumentam a chance no duelo', () => { const a = fresh(), b = fresh(); b.gear.arma = 'pistola'; b.gear.protecao = 'colete'; b.stats.forca = 20; ok(SB.duelOdds(b, SB.rival('galego')) > SB.duelOdds(a, SB.rival('galego')) + 30); });
t('duelo: respeito, limite diário, energia e ferimento grave bloqueiam', () => { const s = fresh(); eq(SB.perform(s, 'duel', 'rei').ok, false); for (let i = 0; i < 3; i++) { s.health = 100; s.energy = 100; s.jail = 0; s.hospital = 0; eq(SB.perform(s, 'duel', 'marrento').ok, true); } s.health = 100; eq(SB.perform(s, 'duel', 'marrento').ok, false); const f = fresh(); f.health = 20; eq(SB.perform(f, 'duel', 'marrento').ok, false); f.health = 100; f.energy = 10; eq(SB.perform(f, 'duel', 'marrento').ok, false); });
t('primeira vitória contra um adversário vale respeito em dobro', () => { let ok2 = false; for (let i = 0; i < 40 && !ok2; i++) { const s = fresh(); s.stats.forca = 40; const r0 = s.respect; SB.perform(s, 'duel', 'marrento'); if (s.duelStats.wins === 1) { eq(s.respect - r0, 2); ok2 = true; } } ok(ok2, 'nenhuma vitória em 40 tentativas'); });
t('derrota no duelo custa saúde e 5% do caixa', () => { let seen = false; for (let i = 0; i < 60 && !seen; i++) { const s = fresh(); s.cash = 1000; s.respect = 200; SB.perform(s, 'duel', 'carcara'); if (s.duelStats.losses === 1) { ok(s.health < 100); ok(s.cash <= 950 && s.cash >= 949); seen = true; } } ok(seen); });
t('proteção reduz o dano recebido', () => { const dmg = prot => { let t2 = 0; for (let i = 0; i < 80; i++) { const s = fresh(); s.respect = 200; s.gear.protecao = prot; SB.perform(s, 'duel', 'rei'); t2 += 100 - s.health; } return t2; }; SB.setRandom(SB.seeded(77)); const a = dmg(null); SB.setRandom(SB.seeded(77)); const b = dmg('tatico'); ok(b < a, `${b} >= ${a}`); });
t('saúde zero interna por 2 dias e bloqueia ações físicas, não o banco', () => { const s = fresh(); s.health = 1; s.cash = 5000; s.respect = 300; s.gangName = 'X'; s.crew = [{ id: 1, name: 'A', role: 'musculo', level: 1, xp: 0 }, { id: 2, name: 'B', role: 'olheiro', level: 1, xp: 0 }]; s.crewMorale = 70; s.gangLevel = 1; for (let i = 0; i < 20 && !s.hospital; i++) { s.today.op = false; s.energy = 100; s.health = 30; SB.perform(s, 'gangOp'); s.health = Math.min(s.health, 1); if (!s.hospital) { s.health = 30; } } s.hospital = 2; s.health = 35; for (const a of [['mission', 'correria'], ['train', 'forca'], ['travel', 'cais'], ['duel', 'marrento'], ['night', 'boteco'], ['contact']]) eq(SB.perform(s, ...a).ok, false, a[0]); eq(SB.perform(s, 'bank', 'deposit', 100).ok, true); SB.perform(s, 'nextDay'); eq(s.hospital, 1); SB.perform(s, 'nextDay'); eq(s.hospital, 0); eq(s.health, 65); });
t('chegar a zero de saúde interna e cobra a conta', () => { const s = fresh(); s.cash = 1000; s.respect = 300; s.health = 26; let n = 0; while (!s.hospital && n++ < 50) { s.today.duels = 0; s.energy = 100; s.health = Math.max(s.health, 26); SB.perform(s, 'duel', 'rei'); } eq(s.hospital, 2); eq(s.health, 35); ok(s.cash <= 700); });
t('saúde baixa reduz as chances de serviço', () => { const a = fresh(), b = fresh(); b.health = 30; eq(SB.missionChance(b, SB.mission('correria')), SB.missionChance(a, SB.mission('correria')) - 12); });
t('posto: +25 uma vez por dia; clínica: cheia por R$ 12 o ponto', () => { const s = fresh(); s.health = 40; eq(SB.perform(s, 'clinic', 'posto').ok, true); eq(s.health, 65); eq(s.energy, 80); eq(SB.perform(s, 'clinic', 'posto').ok, false); const c = s.cash; eq(SB.perform(s, 'clinic', 'clinica').ok, true); eq(s.health, 100); eq(s.cash, c - 35 * 12); eq(SB.perform(s, 'clinic', 'clinica').ok, false); });
t('saúde volta +10 por dia', () => { const s = fresh(); s.health = 50; SB.perform(s, 'nextDay'); eq(s.health, 60); });
t('derrota em confronto fere; ferido não confronta nem opera', () => { const s = withGang(3); s.influence.centro = 30; s.health = 20; eq(SB.perform(s, 'clash', 'esquina').ok, false); s.energy = 100; eq(SB.perform(s, 'gangOp').ok, false); });

console.log('Arsenal, noite e cadeia (v0.9)');
