t('serviços com exigência de arma', () => { const s = fresh(); s.respect = 80; s.gear.veiculo = 'opala'; ok(SB.missionLock(s, SB.mission('loterica')).includes('poder 7')); s.gear.arma = 'maquita'; ok(SB.missionLock(s, SB.mission('loterica')).includes('poder 7')); eq(SB.missionLock(s, SB.mission('caixa')), ''); s.gear.arma = 'trezoitao'; eq(SB.missionLock(s, SB.mission('loterica')), ''); });
t('Termas VIP: exige respeito, enche a energia, sem risco, relação +5', () => { const s = rich(); s.respect = 10; s.energy = 10; eq(SB.perform(s, 'night', 'termas').ok, false); s.respect = 60; const r0 = s.factions.esquina.relation; eq(SB.perform(s, 'night', 'termas').ok, true); eq(s.energy, 10); eq(s.health, 100); eq(s.factions.esquina.relation, r0 + 5); eq(SB.perform(s, 'dose', 'po').ok, true); eq(s.energy, 100); eq(s.vicio, 30); });
