t('carcereiro: mais barato que o advogado, 1 vez por dia, pode dar +1 dia', () => { let up = 0, out = 0; for (let i = 0; i < 80; i++) { const s = fresh(); s.cash = 5000; s.jail = 2; ok(SB.bribeCost(s) < SB.bailCost(s)); SB.perform(s, 'bribe'); if (s.jail === 0) out++; if (s.jail === 3) up++; eq(SB.perform(s, 'bribe').ok, false); } ok(up > 0 && out > 0); });

console.log('Assaltos do bando (v1.0)');
const bando = (n = 3) => { const s = withGang(n); s.cash = 30000; s.respect = 200; s.gangLevel = 6; s.gear.arma = 'rojao'; s.energy = 100; return s; };
t('save antigo entra sem assalto planejado; plano adulterado é limpo', () => { eq(SB.parseSave(JSON.stringify(v04)).state.heist, null); const s = bando(); s.heist = { id: 'falso', day: 1 }; eq(SB.parseSave(JSON.stringify(s)).state.heist, null); s.heist = { id: 'arrastao', day: 3, intel: 999, hires: 50 }; const n = SB.parseSave(JSON.stringify(s)).state.heist; eq(n.intel, 40); eq(n.hires, 4); });
t('requisitos: gangue, respeito, sede, arma do líder e no máximo 4 avulsos', () => { const s = fresh(); ok(SB.heistLock(s, SB.heist('arrastao')).includes('gangue')); const b = bando(2); b.respect = 10; ok(SB.heistLock(b, SB.heist('arrastao')).includes('respeito')); b.respect = 200; b.gangLevel = 1; ok(SB.heistLock(b, SB.heist('rodovia')).includes('sede')); b.gangLevel = 6; b.gear.arma = 'peixeira'; ok(SB.heistLock(b, SB.heist('rodovia')).includes('arma')); b.gear.arma = 'rojao'; ok(SB.heistLock(b, SB.heist('cofrecentral')).includes('avulsos')); eq(SB.heistLock(b, SB.heist('arrastao')), ''); });
t('plano cobra avulsos que faltam e precisa de uma noite antes da execução', () => { const s = bando(3); const c = s.cash; eq(SB.perform(s, 'heistPlan', 'rodovia').ok, true); eq(s.heist.hires, 2); eq(s.cash, c - 900 - 2 * 450); eq(SB.perform(s, 'heistRun').ok, false); eq(SB.perform(s, 'heistPlan', 'arrastao').ok, false); });
t('reconhecimento: 1 vez por dia, sobe a chance, teto 40', () => { const s = bando(3); SB.perform(s, 'heistPlan', 'arrastao'); const o0 = SB.heistOdds(s, SB.heist('arrastao')); eq(SB.perform(s, 'heistScout').ok, true); ok(SB.heistOdds(s, SB.heist('arrastao')) >= o0 || o0 === 90); eq(SB.perform(s, 'heistScout').ok, false); for (let i = 0; i < 5; i++) { s.energy = 100; s.heist.scoutDay = 0; SB.perform(s, 'heistScout'); } eq(s.heist.intel, 40); });
t('execução: sucesso paga 75%, esfria 3 dias; falha cobra caro', () => { let okRun = false, badRun = false; for (let i = 0; i < 60 && !(okRun && badRun); i++) { const s = bando(3); s.crewMorale = 70; SB.perform(s, 'heistPlan', 'agencia'); s.day++; s.energy = 100; const c = s.cash, r = SB.perform(s, 'heistRun'); ok(r.ok); eq(s.heist, null); eq(s.heistReady, s.day + 3); if (r.good) { okRun = true; ok(s.cash - c >= Math.round(9000 * .6 * .75) - 1); eq(s.gangStats.heists, 1); ok(s.achievements.primeiroassalto); } else { badRun = true; eq(s.gangStats.heistFails, 1); ok(s.cash < c); } } ok(okRun && badRun, `ok=${okRun} bad=${badRun}`); });
t('plano expira depois do prazo e o bando perde ânimo', () => { const s = bando(3); SB.perform(s, 'heistPlan', 'arrastao'); const m = s.crewMorale; for (let i = 0; i < 6; i++) SB.perform(s, 'nextDay'); eq(s.heist, null); ok(s.crewMorale < m + 10); });
t('não executa sem gente, com ânimo baixo, ferido ou sem a arma', () => { const s = bando(3); SB.perform(s, 'heistPlan', 'rodovia'); s.day++; s.crewMorale = 20; eq(SB.perform(s, 'heistRun').ok, false); s.crewMorale = 70; s.health = 20; eq(SB.perform(s, 'heistRun').ok, false); s.health = 100; s.gear.arma = 'soco'; eq(SB.perform(s, 'heistRun').ok, false); s.gear.arma = 'rojao'; s.crew = s.crew.slice(0, 1); eq(SB.perform(s, 'heistRun').ok, false); });
t('cancelar devolve nada e baixa o ânimo', () => { const s = bando(3); SB.perform(s, 'heistPlan', 'arrastao'); const c = s.cash, m = s.crewMorale; eq(SB.perform(s, 'heistCancel').ok, true); eq(s.cash, c); eq(s.crewMorale, m - 5); eq(SB.perform(s, 'heistCancel').ok, false); });
t('assaltos contam na categoria Gangue', () => { const s = bando(3); const v = SB.categoryValue(s, 'gangue'); s.gangStats.heists = 2; eq(SB.categoryValue(s, 'gangue'), v + 30); });

