t('Traficante: produção mais barata e maior, comprador paga mais', () => { const a = rich(), b = rich(); b.career = 'traficante'; const l = SB.LABS.find(x => x.id === 'alambique'); ok(SB.labCost(b, l) < SB.labCost(a, l)); a.labs.alambique = b.labs.alambique = 1; ok(SB.labOutput(b, l) > SB.labOutput(a, l)); ok(SB.exportPrice(SB.good('erva'), b) > SB.exportPrice(SB.good('erva'), a)); });
