t('Dono da Noite: casas rendem mais, noite mais barata, vício pela metade só no forte', () => { const a = rich(), b = rich(); b.career = 'barao'; a.businesses = b.businesses = ['inferninho']; ok(SB.income(b) > SB.income(a)); ok(SB.nightCost(b, SB.NIGHT[2]) < SB.nightCost(a, SB.NIGHT[2])); a.energy = b.energy = 0; SB.setRandom(SB.seeded(1)); SB.perform(a, 'night', 'boteco'); SB.perform(b, 'night', 'boteco'); SB.perform(a, 'dose', 'pinga'); SB.perform(b, 'dose', 'pinga'); eq(a.vicio, 2); eq(b.vicio, 2, 'pinga não tem desconto'); eq(SB.doseVicio(b, SB.doseOf('bala')), 9); eq(SB.doseVicio(a, SB.doseOf('bala')), 18); ok(SB.doseCost(b, SB.doseOf('pinga')) < SB.doseCost(a, SB.doseOf('pinga'))); });
t('negócios novos: nomes fixos em qualquer cidade e renda', () => { SB.applyCity('São Paulo'); eq(SB.business('termas').name, 'Termas VIP'); eq(SB.business('bicho').name, 'Banca do bicho'); SB.applyCity('Recife'); const s = rich(); eq(SB.perform(s, 'buy', 'pensao').ok, true); ok(SB.income(s) > 0); });
t('Termas própria: 1 recarga cheia por dia, grátis, sem vício e sem exigir respeito', () => { const s = fresh(); s.businesses = ['termas']; s.energy = 5; s.vicio = 50; const c = s.cash; eq(SB.perform(s, 'night', 'termas').ok, true); eq(s.energy, 100); eq(s.cash, c); eq(s.vicio, 50); s.energy = 5; eq(SB.perform(s, 'night', 'termas').ok, false); });
t('vício reduz a recarga, cai 3 por dia e pode dar overdose', () => { const s = rich(); s.vicio = 80; ok(SB.nightEnergy(s, SB.doseOf('lolo')) < 50 * .6); eq(SB.overdoseChance(s), 20); s.vicio = 50; eq(SB.overdoseChance(s), 0); SB.perform(s, 'nextDay'); eq(s.vicio, 47); let od = 0; for (let i = 0; i < 80; i++) { const x = rich(); x.vicio = 95; x.energy = 0; x.respect = 100; SB.perform(x, 'night', 'baile'); SB.perform(x, 'dose', 'lolo'); if (x.hospital === 1) { od++; ok(x.respect < 100); ok(x.health < 100); } } ok(od > 5 && od < 60, String(od)); });
t('desintoxicação: soro (1 por dia) e clínica (zera)', () => { const s = rich(); eq(SB.perform(s, 'detox', 'soro').ok, false); s.vicio = 50; eq(SB.perform(s, 'detox', 'soro').ok, true); eq(s.vicio, 30); eq(SB.perform(s, 'detox', 'soro').ok, false); const c = s.cash; eq(SB.perform(s, 'detox', 'clinica').ok, true); eq(s.vicio, 0); eq(s.cash, c - 30 * 18); });
t('batida policial nos lugares baratos tem multa limitada', () => { let hit = 0; for (let i = 0; i < 200; i++) { const s = rich(); s.energy = 0; const c = s.cash; SB.perform(s, 'night', 'boteco'); const paid = c - 40 - s.cash; if (paid > 0) { hit++; ok(paid <= 500); } } ok(hit > 3 && hit < 60, String(hit)); });
t('apostas: limites, teto e resultado coerente', () => { const s = fresh(); for (const st of [0, 5, 1.5, 1e9, NaN]) eq(SB.perform(s, 'bet', 'roleta', st).ok, false, String(st)); eq(SB.perform(s, 'bet', 'roleta', 5000).ok, false); eq(SB.perform(s, 'bet', 'sinuca', 1900).ok, true); eq(SB.perform(s, 'bet', 'bicho', 100, 99).ok, false); eq(SB.perform(s, 'bet', 'xis', 100).ok, false); const r = rich(); r.cash = 100000; eq(SB.perform(r, 'bet', 'sinuca', 2001).ok, false); for (let i = 0; i < 6; i++) eq(SB.perform(r, 'bet', 'roleta', 100).ok, true); eq(SB.perform(r, 'bet', 'roleta', 100).ok, false); eq(r.cash, 100000 + r.betStats.won - r.betStats.lost); });
t('a banca sempre tem vantagem (10 mil apostas de cada jogo)', () => { SB.setRandom(SB.seeded(42)); for (const [g, pick] of [['roleta'], ['sinuca'], ['bicho', 7]]) { const s = fresh(); s.cash = 1e9; s.stats.astucia = 99; s.stats.labia = 99; s.career = 'empreendedor'; const c = s.cash; for (let i = 0; i < 10000; i++) { s.today.bets = 0; SB.perform(s, 'bet', g, 100, pick); } ok(s.cash < c, g + ' deu lucro'); } });
t('colete segura a trocação no roubo armado que falha', () => { const dmg = prot => { SB.setRandom(SB.seeded(11)); let t2 = 0, n = 0; for (let i = 0; i < 400; i++) { const s = fresh(); s.respect = 100; s.gear.arma = 'trezoitao'; s.gear.veiculo = 'opala'; s.gear.protecao = prot; s.stats.forca = 1; s.heat = 100; SB.perform(s, 'mission', 'loterica'); if (s.failed) { n++; t2 += 100 - s.health; } } return t2 / n; }; const semColete = dmg(null), comColete = dmg('tatico'); ok(semColete > 15, String(semColete)); ok(comColete < semColete - 5, `${comColete} x ${semColete}`); });
t('ser preso custa respeito', () => { let seen = false; for (let i = 0; i < 80 && !seen; i++) { const s = fresh(); s.successful = 1; s.respect = 100; s.heat = 100; s.stats.astucia = 1; SB.perform(s, 'mission', 'correria'); if (s.jail > 0) { eq(s.respect, 96); seen = true; } } ok(seen); });
t('despachante: limpa a ficha uma vez por dia', () => { const s = rich(); eq(SB.perform(s, 'cleanRecord').ok, false); s.heat = 70; const c = s.cash; eq(SB.perform(s, 'cleanRecord').ok, true); eq(s.heat, 35); eq(s.cash, c - (150 + 70 * 14)); eq(SB.perform(s, 'cleanRecord').ok, false); });
t('calendário: pagamento nos dias 5 e 20, fluxo no 6, fecha-mês do 28 ao 30', () => { const s = fresh(); const ids = d => { while (s.day < d) SB.perform(s, 'nextDay'); return SB.activeEvents(s).map(e => e.id); }; ok(ids(5).includes('pagamento')); ok(ids(6).includes('fluxo')); ok(!ids(8).includes('fluxo')); ok(ids(20).includes('pagamento')); ok(ids(28).includes('fechames')); ok(ids(30).includes('fechames')); });
t('dia de pagamento engorda lotérica e assaltos; noite de fluxo dobra as casas', () => { const s = rich(); s.gear.arma = 'trezoitao'; const m0 = SB.missionRewardMult(s, SB.mission('loterica')); s.events = [{ id: 'pagamento', start: 1, until: 1, district: null }]; ok(Math.abs(SB.missionRewardMult(s, SB.mission('loterica')) / m0 - 1.3) < .001); eq(SB.missionRewardMult(s, SB.mission('correria')), SB.missionRewardMult(fresh(), SB.mission('correria'))); const b = rich(); b.businesses = ['inferninho', 'mercado']; const i0 = SB.businessIncome(b, SB.business('inferninho')), m1 = SB.businessIncome(b, SB.business('mercado')); b.events = [{ id: 'fluxo', start: 1, until: 1, district: null }]; eq(SB.businessIncome(b, SB.business('inferninho')), i0 * 2); eq(SB.businessIncome(b, SB.business('mercado')), m1); });
t('semanas do mês', () => { const s = fresh(); ok(SB.week(s).name.includes('Semana 1')); s.day = 8; ok(SB.week(s).name.includes('Semana 2')); s.day = 23; ok(SB.week(s).name.includes('Semana 3')); s.day = 30; ok(SB.week(s).name.includes('Semana 4')); });
