t('retrato: escolha, recusa sem mudar o estado, save e nova temporada', () => { const s = fresh(); eq(s.avatar, null); const c = JSON.stringify(s); eq(SB.perform(s, 'avatar', 'xyz').ok, false); eq(SB.perform(s, 'avatar', 'none').ok, false); eq(JSON.stringify(s), c); eq(SB.perform(s, 'avatar', 'gaucho').ok, true); eq(s.avatar, 'gaucho'); eq(SB.parseSave(JSON.stringify(s)).state.avatar, 'gaucho'); const bad = JSON.parse(JSON.stringify(s)); bad.avatar = '<img onerror=1>'; eq(SB.parseSave(JSON.stringify(bad)).state.avatar, null); s.day = 30; const r = SB.perform(s, 'endSeason'); eq(r.state.avatar, 'gaucho'); eq(SB.perform(s, 'avatar', 'none').ok, true); eq(s.avatar, null); });

console.log('Relógio do modo online (v1.5)');
const T0 = Date.UTC(2026, 10, 13, 15, 0, 0); // 13/11/2026, 12:00 em Brasília
const MIN = 60000, H = 3600000;
const clocked = () => SB.startClock(fresh(), T0);
t('ligar o relógio: o dia do jogo é o dia do mês; sem relógio, tick não faz nada', () => { const s = clocked(); eq(s.day, 13); eq(s.clock.day, '2026-11-13'); eq(s.clock.month, '2026-11'); const o = fresh(); const c = JSON.stringify(o); SB.tick(o, T0 + H); eq(JSON.stringify(o), c); });
t('energia: +1 a cada 3 minutos, sem passar de 100 e sem guardar sobra', () => { const s = clocked(); s.energy = 10; SB.tick(s, T0 + 3 * MIN - 1); eq(s.energy, 10); SB.tick(s, T0 + 3 * MIN); eq(s.energy, 11); SB.tick(s, T0 + 63 * MIN); eq(s.energy, 31); SB.tick(s, T0 + 10 * H); eq(s.energy, 100); s.energy = 50; SB.tick(s, T0 + 10 * H + 3 * MIN); eq(s.energy, 51); });
t('tempo não anda para trás nem com data inválida', () => { const s = clocked(); s.energy = 10; SB.tick(s, T0 + 30 * MIN); const c = JSON.stringify(s); SB.tick(s, T0); SB.tick(s, NaN); SB.tick(s, 'x'); eq(JSON.stringify(s), c); });
t('online o Procurado cai 4x mais rápido (60 por dia, aos poucos); vício cai 1 a cada 8 horas', () => { const s = clocked(); s.heat = 50; s.vicio = 30; s.events = []; SB.tick(s, T0 + 8 * H); eq(s.heat, 30); eq(s.vicio, 29); });
t('cadeia e hospital: 1 dia do jogo vale 2 horas', () => { const s = clocked(); s.jail = 2; SB.tick(s, T0 + 2 * H - 1); eq(s.jail, 2); eq(SB.clockInfo(s).lock, 2 * H + 1); SB.tick(s, T0 + 2 * H); eq(s.jail, 1); SB.tick(s, T0 + 4 * H); eq(s.jail, 0); const h = clocked(); h.hospital = 1; h.health = 40; SB.tick(h, T0 + 2 * H); eq(h.hospital, 0); eq(h.health, 55); });
t('virada à meia-noite de Brasília: renda entra, limites do dia zeram, energia não ganha +70', () => { const s = clocked(); s.energy = 0; s.businesses = ['oficina']; s.today.night = 3; s.events = []; const c = s.cash; SB.setRandom(SB.seeded(4)); const r = SB.tick(s, T0 + 12 * H + 1); eq(s.day, 14); eq(s.clock.day, '2026-11-14'); ok(s.cash > c, 'renda'); eq(s.today.night, 0); eq(s.energy, 100, 'só a regeneração de 12 h, com teto'); ok(r.lines.some(l => l.includes('Virou o dia 14'))); });
t('ausência de 3 dias: três viradas com renda', () => { const s = clocked(); s.businesses = ['oficina']; const c = s.cash; SB.tick(s, T0 + 3 * 24 * H); eq(s.day, 16); ok(s.cash > c + 300); });
t('previsão no aparelho para antes da meia-noite e avisa que há virada pendente', () => { const s = clocked(); s.energy = 0; const r = SB.tick(s, T0 + 13 * H, { local: true }); eq(r.pending, true); eq(s.day, 13); ok(s.energy > 0); });
t('fim do mês fecha a temporada sozinho e o ranking recomeça', () => { const s = clocked(); s.respect = 150; const r = SB.tick(s, Date.UTC(2026, 11, 1, 3, 0, 1)); const n = r.state; eq(n.season, 2); eq(n.day, 1); eq(n.clock.month, '2026-12'); eq(n.seasonHistory.length, 1); ok(n.respect < 150); ok(r.lines.some(l => l.includes('temporada nova'))); });
t('ausência de meses: retoma de agora sem travar', () => { const s = clocked(); const r = SB.tick(s, Date.UTC(2027, 3, 10, 15, 0, 0)); eq(r.state.clock.month, '2027-04'); eq(r.state.day, 10); ok(r.state.season >= 2); });
t('com relógio, Dormir e Encerrar temporada são recusados, mesmo com argumento forjado', () => { const s = clocked(); const c = JSON.stringify(s); eq(SB.perform(s, 'nextDay').ok, false); eq(SB.perform(s, 'nextDay', 20).ok, false); eq(SB.perform(s, 'endSeason', true).ok, false); eq(JSON.stringify(s), c); const o = fresh(); eq(SB.perform(o, 'nextDay', 25).ok, true); eq(o.day, 2, 'argumento ignorado no jogo local'); eq(SB.perform(o, 'endSeason', true).ok, false); });
t('ir pra casa: 3 horas parado, depois energia cheia e corpo zerado; 2 vezes por dia', () => { const s = clocked(); s.cash = 5000; s.energy = 20; SB.perform(s, 'night', 'boteco'); SB.perform(s, 'dose', 'pinga'); ok(s.today.chem > 0); eq(SB.perform(s, 'goHome').ok, true); ok(SB.atHome(s)); eq(SB.perform(s, 'mission', 'correria').ok, false); eq(SB.perform(s, 'bank', 'deposit', 100).ok, true, 'banco continua'); SB.tick(s, T0 + 3 * H - 1); ok(SB.atHome(s)); SB.tick(s, T0 + 3 * H); eq(SB.atHome(s), false); eq(s.energy, 100); eq(s.today.chem, 0); eq(s.today.doses, 0); eq(SB.perform(s, 'goHome').ok, false, 'inteiro não precisa'); s.energy = 10; eq(SB.perform(s, 'goHome').ok, true); SB.tick(s, T0 + 7 * H); s.energy = 10; eq(SB.perform(s, 'goHome').ok, false, 'terceira vez no dia'); });
t('sair de casa antes da hora não dá o descanso; no jogo local não existe ir pra casa', () => { const s = clocked(); s.energy = 20; SB.perform(s, 'goHome'); SB.tick(s, T0 + H); eq(SB.perform(s, 'leaveHome').ok, true); eq(s.energy, 40); eq(SB.atHome(s), false); const o = fresh(); o.energy = 10; eq(SB.perform(o, 'goHome').ok, false); eq(SB.perform(o, 'leaveHome').ok, false); });
t('relógio adulterado no save é limitado; ida e volta estável', () => { const s = clocked(); const a = JSON.stringify(s); eq(JSON.stringify(SB.parseSave(a).state), a); s.clock = { t: 1e30, day: '<x>', month: 7, home: -5, e: 9e12, h: 'a', v: null, j: -1 }; const n = SB.parseSave(JSON.stringify(s)).state.clock; eq(n.t, 1e14); ok(/^\d{4}-\d{2}-\d{2}$/.test(n.day)); ok(/^\d{4}-\d{2}$/.test(n.month)); eq(n.home, 0); eq(n.e, 864e5); eq(n.h, 0); eq(n.j, 0); s.clock = { t: 'x' }; eq(SB.parseSave(JSON.stringify(s)).state.clock, null); });
