t('roubos grandes pedem veículo de fuga', () => { const s = fresh(); s.respect = 200; s.gangName = 'X'; s.stats.astucia = 30; s.gear.arma = 'doze'; ok(SB.missionLock(s, SB.mission('cofre')).includes('Moto 150')); s.gear.veiculo = 'cinquentinha'; ok(SB.missionLock(s, SB.mission('cofre')).includes('veículo')); eq(SB.missionLock(s, SB.mission('loterica')), ''); s.gear.veiculo = 'moto'; eq(SB.missionLock(s, SB.mission('cofre')), ''); const c = JSON.stringify(s); s.gear.veiculo = null; const c2 = JSON.stringify(s); eq(SB.perform(s, 'mission', 'caixa').ok, false); eq(JSON.stringify(s), c2); });
console.log('Feitos do mês (v1.5)');
t('feitos do mês pagam respeito uma vez por medalha', () => { const s = newbie(); s.tutorial.done = true; const r0 = s.respect; s.cash = 6500; const r = SB.perform(s, 'bank', 'deposit', 100); ok(r.lines.some(l => l.includes('Fortuna Bronze')), 'aparece no resultado'); eq(s.respect, r0 + SB.FEAT_RESPECT[1]); s.cash = 20000; SB.perform(s, 'bank', 'deposit', 100); eq(s.feats.fortuna, 3); eq(s.respect, r0 + SB.FEAT_RESPECT[1] + SB.FEAT_RESPECT[2] + SB.FEAT_RESPECT[3]); s.cash = 0; const r1 = s.respect; SB.perform(s, 'bank', 'withdraw', 50); eq(s.respect, r1, 'perder o patrimônio não paga de novo nem tira'); });
t('save antigo não ganha feitos de graça; feitos zeram na temporada nova', () => { const s = newbie(); s.cash = 20000; const raw = JSON.parse(JSON.stringify(s)); delete raw.feats; const n = SB.parseSave(JSON.stringify(raw)).state; eq(n.feats.fortuna, 3); const r0 = n.respect; n.tutorial.done = true; SB.perform(n, 'bank', 'deposit', 100); eq(n.respect, r0); n.day = 30; const nx = SB.perform(n, 'endSeason').state; eq(nx.feats.fortuna, 0); eq(nx.seasonHistory.at(-1).score, n.respect); });
console.log('Quatro classes (v1.4)');
t('Assaltante: +15% no roubo, 10% menos energia, arma e colete +15%; esquemas e negócios −10%', () => { const a = rich(), b = rich(); b.career = 'operador'; const m = SB.mission('correria'); eq(Math.round(SB.missionRewardMult(b, m) * 100), Math.round(SB.missionRewardMult(a, m) * 115)); eq(SB.missionCost(b, SB.mission('cofre')), Math.round(SB.mission('cofre').cost * .9)); a.gear.arma = b.gear.arma = 'trezoitao'; a.gear.protecao = b.gear.protecao = 'colete'; ok(SB.armPower(b) > SB.armPower(a)); ok(SB.armDef(b) > SB.armDef(a)); ok(SB.combatRating(b) > SB.combatRating(a)); a.labs.alambique = b.labs.alambique = 1; const l = SB.LABS.find(x => x.id === 'alambique'); ok(SB.labOutput(b, l) < SB.labOutput(a, l)); });
t('Dono da Noite: casas +30% e 20% mais baratas; a arma conta 20% menos nos roubos', () => { const a = rich(), b = rich(); b.career = 'barao'; eq(SB.buyCost(b, SB.business('inferninho')), Math.round(4200 * .8)); eq(Math.round(SB.businessIncome(b, SB.business('inferninho'))), Math.round(SB.businessIncome(a, SB.business('inferninho')) * 1.3)); a.gear.arma = b.gear.arma = 'trezoitao'; ok(SB.armPower(b, true) < SB.armPower(a, true)); eq(SB.armPower(b), SB.armPower(a), 'fora dos roubos a arma conta igual'); const m = SB.MISSIONS.find(x => x.req && x.req.power); a.respect = b.respect = 300; ok(SB.missionChance(b, m) < SB.missionChance(a, m)); });
t('Traficante: +25% de produção e +10% no Navio; esquema de mercadoria ativo dá +1 de Procurado por dia', () => { const a = rich(), b = rich(); b.career = 'traficante'; const l = SB.LABS.find(x => x.id === 'plantacao'); a.labs.plantacao = b.labs.plantacao = 1; eq(SB.labOutput(b, l), Math.round(6 * 1.25)); eq(SB.exportPrice(SB.good('po'), b), Math.round(300 * 1.9 * 1.1)); a.heat = b.heat = 50; a.labs.gatonet = b.labs.gatonet = 1; SB.setRandom(SB.seeded(3)); SB.perform(a, 'nextDay'); SB.setRandom(SB.seeded(3)); SB.perform(b, 'nextDay'); ok(b.heat === a.heat + 1 || b.labDown.plantacao >= b.day, `${b.heat} × ${a.heat}`); });
t('Bicheiro: banco pela metade, advogado 30% mais barato, respeito pelo dinheiro guardado; Força custa mais', () => { const a = fresh(), b = fresh(); b.career = 'empreendedor'; eq(SB.depositFee(b, 1000), 15); eq(SB.depositFee(a, 1000), 30); a.jail = b.jail = 2; eq(SB.bailCost(b), Math.round(SB.bailCost(a) * .7)); ok(Math.abs(SB.trainCost(b, 'forca') - SB.trainCost(a, 'forca') * 1.25) <= 1); eq(SB.trainCost(b, 'astucia'), SB.trainCost(a, 'astucia')); a.jail = b.jail = 0; ok(SB.missionChance(b, SB.mission('correria')) <= SB.missionChance(a, SB.mission('correria'))); b.bank = 35000; const r = b.respect; SB.perform(b, 'nextDay'); eq(b.respect - r >= 3, true); b.labs.gatonet = 1; eq(SB.labCash(b, SB.LABS.find(x => x.id === 'gatonet')), 270); });
console.log('Noite com cardápio e esquemas de produção (v1.4)');
t('dose: só dentro da casa, só o que ela vende, limites e recusa sem mudar o estado', () => { const s = rich(); s.energy = 0; let c = JSON.stringify(s); eq(SB.perform(s, 'dose', 'cerveja').ok, false); eq(JSON.stringify(s), c); SB.perform(s, 'night', 'boteco'); c = JSON.stringify(s); eq(SB.perform(s, 'dose', 'po').ok, false); eq(SB.perform(s, 'dose', 'xyz').ok, false); eq(JSON.stringify(s), c); for (let i = 0; i < 5; i++) eq(SB.perform(s, 'dose', 'cigarro').ok, true); eq(s.energy, 7, 'cigarro com tolerância: 2+2+1+1+1'); eq(s.vicio, 0); eq(SB.perform(s, 'dose', 'cigarro').ok, false); for (let i = 0; i < 10; i++) { s.energy = 0; eq(SB.perform(s, 'dose', 'cerveja').ok, true); } s.energy = 0; eq(SB.perform(s, 'dose', 'cerveja').ok, false, 'limite de 15 doses'); });
t('cardápio: mais forte, mais energia e mais vício; Inferninho abre com 40 de respeito', () => { for (let i = 1; i < SB.DOSES.length; i++) { ok(SB.DOSES[i].energy > SB.DOSES[i - 1].energy); ok(SB.DOSES[i].vicio >= SB.DOSES[i - 1].vicio); } const s = rich(); s.energy = 0; s.respect = 30; eq(SB.perform(s, 'night', 'inferninho').ok, false); s.respect = 40; eq(SB.perform(s, 'night', 'inferninho').ok, true); eq(SB.perform(s, 'dose', 'bala').ok, true); eq(s.vicio, 18); });
t('tolerância: a mesma dose rende 15% menos a cada vez, por tipo, e zera ao dormir', () => { const s = rich(); s.energy = 0; SB.perform(s, 'night', 'baile'); const got = []; for (let i = 0; i < 4; i++) { const e = s.energy; SB.perform(s, 'dose', 'erva'); got.push(s.energy - e); } eq(got.join(), '30,25,21,17', 'tolerância e vício somados'); const e = s.energy; SB.perform(s, 'dose', 'cerveja'); eq(s.energy - e, 5, 'outro tipo rende cheio'); s.energy = 0; SB.perform(s, 'nextDay'); eq(SB.doseTolerance(s, SB.doseOf('erva')), 1); eq(s.today.chem, 0); });
t('teto do corpo: no máximo 150 de energia em doses por dia, recusa sem mudar o estado', () => { const s = rich(); s.energy = 0; s.respect = 100; SB.perform(s, 'night', 'inferninho'); SB.perform(s, 'dose', 'bala'); s.energy = 0; SB.perform(s, 'dose', 'bala'); eq(s.today.chem, 75 + 57); s.energy = 0; const r = SB.perform(s, 'dose', 'lolo'); eq(r.ok, true); eq(s.today.chem, 150); eq(s.energy, 18, 'só o que faltava para o teto'); s.energy = 0; const c = JSON.stringify(s); eq(SB.perform(s, 'dose', 'cigarro').ok, false); eq(JSON.stringify(s), c); ok(SB.perform(s, 'dose', 'cigarro').msg.includes('descansar')); });
t('dose do próprio estoque não cobra dinheiro', () => { const s = rich(); s.energy = 0; s.goods.erva = 2; SB.perform(s, 'night', 'pagode'); const c = s.cash; eq(SB.perform(s, 'dose', 'erva', true).ok, true); eq(s.cash, c); eq(s.goods.erva, 1); eq(s.energy, 30); s.goods.erva = 0; eq(SB.perform(s, 'dose', 'erva', true).ok, false); });
t('whisky às vezes dá azia (−5 de saúde)', () => { let n = 0; for (let i = 0; i < 300; i++) { const s = rich(); s.energy = 0; SB.perform(s, 'night', 'baile'); s.health = 100; SB.perform(s, 'dose', 'whisky'); if (s.health === 95) n++; } ok(n > 15 && n < 70, String(n)); });
t('sete esquemas em ordem de respeito; gelo e gatonet sem batida', () => { eq(SB.LABS.map(l => l.id).join(), 'gelo,paraguai,alambique,gatonet,plantacao,laboratorio,refinaria'); for (let i = 1; i < SB.LABS.length; i++) ok(SB.LABS[i].unlock >= SB.LABS[i - 1].unlock); const s = rich(); s.heat = 100; s.labs.gelo = 1; s.labs.gatonet = 1; s.labs.alambique = 1; eq(SB.labRaid(s, SB.LABS[0]), 0); eq(SB.labRaid(s, SB.LABS[3]), 0); ok(SB.labRaid(s, SB.LABS[2]) > 0); s.labs.laboratorio = 1; ok(SB.labRaid(s, SB.LABS[5]) < SB.labRaid(s, SB.LABS[2])); });
t('gatonet paga no banco; laboratório produz loló e bala e paga propina', () => { const s = rich(); s.heat = 0; s.labs.gatonet = 1; s.labs.laboratorio = 1; const b = s.bank; eq(SB.labUpkeep(s), 30 + 30 + 60); SB.perform(s, 'nextDay'); eq(s.bank - b, 200); ok(s.goods.bala >= 4 && s.goods.lolo >= 3); });
t('Inferninho abastecido com a sua bebida rende +70% e gasta 5 caixas', () => { const a = rich(), b = rich(); for (const s of [a, b]) { s.heat = 0; s.businesses = ['inferninho']; s.events = []; } b.labs.alambique = 1; b.goods.bebida = 10; SB.setRandom(SB.seeded(5)); const ca = a.cash; SB.perform(a, 'nextDay'); SB.setRandom(SB.seeded(5)); const cb = b.cash; SB.perform(b, 'nextDay'); ok(b.cash - cb > (a.cash - ca) + 100, `${b.cash - cb} × ${a.cash - ca}`); eq(b.goods.bebida, 10 - 5 + 7); const c = rich(); c.businesses = ['inferninho']; c.goods.bebida = 10; eq(SB.supplyPlan(c, SB.SUPPLY[0]), null, 'sem o esquema produtor não abastece'); });
t('pó no Navio dá o triplo de respeito', () => { const mk = g => { const s = rich(); s.district = 'cais'; s.exportDeal = { day: s.day, good: g }; s.goods[g] = 20; return s; }; const a = mk('erva'), b = mk('po'); const ra = a.respect, rb = b.respect; SB.perform(a, 'exportGoods'); SB.perform(b, 'exportGoods'); eq(a.respect - ra, 2); eq(b.respect - rb, 6); });
t('save adulterado da noite é limitado', () => { const s = rich(); s.today.venue = '<img>'; s.today.doses = 9999; s.today.dose = { po: -4, x: 3 }; const n = SB.parseSave(JSON.stringify(s)).state; eq(n.today.venue, null); eq(n.today.doses, 99); eq(n.today.dose.po, 0); eq(n.today.dose.x, undefined); });
t('preços da Feira sobem com o poder: a 2ª arma custa vários roubos iniciais', () => { const g = SB.ITEMS.filter(i => i.slot === 'arma' && !i.trophy); for (let i = 1; i < g.length; i++) ok(g[i].cost > g[i - 1].cost, g[i].id); const top = SB.mission('correria').high; ok(SB.item('porrete').cost + SB.item('soco').cost >= top * 3, 'chegar à Chave de fenda custa ao menos 3 roubos de Bater carteira'); ok(SB.item('porrete').cost <= SB.mission('correria').low * 1.2, 'a primeira arma sai com 1 roubo'); });

